form.script:
(function() {
    var el = document.getElementById('enquiry_subject_data');
    var subjectsByCategory = JSON.parse(el.getAttribute('data-subjects') || '{}');
    var gradesByCategory = JSON.parse(el.getAttribute('data-grades') || '{}');
    var container = document.getElementById('students_container');
    var addBtn = document.getElementById('add_student_btn');
    var nextIdx = 0;

    // Looked up lazily (not at script-parse time): the
    // #student_block_template element is deliberately placed
    // after the closing form tag in the markup (see the comment
    // there), which is also after this script block, so it
    // doesn't exist yet when this IIFE runs. By the time a user
    // can click "Add Another Student" the whole page has parsed,
    // so this resolves correctly on first use.
    function getTemplateBlock() {
        return document.querySelector('#student_block_template .student-block');
    }

    function allBlocks() {
        return Array.prototype.slice.call(container.querySelectorAll('.student-block'));
    }

    function updateRemoveButtons() {
        var blocks = allBlocks();
        blocks.forEach(function(block) {
            var btn = block.querySelector('.remove-student-btn');
            btn.style.display = blocks.length > 1 ? 'inline-block' : 'none';
        });
    }

    function initStudentBlock(idx) {
        var catSel = document.getElementById('field_category_' + idx);
        var subSel = document.getElementById('field_subject_' + idx);
        var gradeSel = document.getElementById('field_grade_' + idx);
        var block = catSel.closest('.student-block');
        var subHidden = block.querySelector('.student-selected-subject');
        var gradeHidden = block.querySelector('.student-selected-grade');
        var selectedSubject = subHidden ? subHidden.value : '';
        var selectedGrade = gradeHidden ? gradeHidden.value : '';

        function filterGrades(resetValue) {
            var catId = catSel.value;
            var keepVal = resetValue ? '' : selectedGrade;
            while (gradeSel.options.length > 1) { gradeSel.remove(1); }
            var list = catId
                ? (gradesByCategory[catId] || [])
                : Object.values(gradesByCategory).reduce(function(a, b) {
                    var seen = {};
                    return a.concat(b.filter(function(g) {
                        return seen[g.id] ? false : (seen[g.id] = true);
                    }));
                  }, []);
            list.forEach(function(g) {
                var opt = document.createElement('option');
                opt.value = g.id;
                opt.textContent = g.name;
                if (String(g.id) === String(keepVal)) { opt.selected = true; }
                gradeSel.appendChild(opt);
            });
        }

        function filterSubjects(resetValue) {
            var catId = catSel.value;
            var keepVal = resetValue ? '' : (subSel.value || selectedSubject);
            while (subSel.options.length > 1) { subSel.remove(1); }
            var list = catId
                ? (subjectsByCategory[catId] || [])
                : Object.values(subjectsByCategory).reduce(function(a, b) { return a.concat(b); }, []);
            list.forEach(function(s) {
                var opt = document.createElement('option');
                opt.value = s.id;
                opt.textContent = s.name;
                if (String(s.id) === String(keepVal)) { opt.selected = true; }
                subSel.appendChild(opt);
            });
        }

        catSel.addEventListener('change', function() {
            filterGrades(true);
            filterSubjects(true);
        });

        filterGrades(false);
        filterSubjects(false);
    }

    function addStudentBlock() {
        var idx = nextIdx++;
        var html = getTemplateBlock().outerHTML.split('__IDX__').join(idx);
        var wrapper = document.createElement('div');
        wrapper.innerHTML = html;
        var block = wrapper.firstElementChild;
        block.querySelector('strong').textContent = 'Student ' + (allBlocks().length + 1);
        container.appendChild(block);
        initStudentBlock(idx);
        updateRemoveButtons();
    }

    container.addEventListener('click', function(ev) {
        var btn = ev.target.closest('.remove-student-btn');
        if (!btn) { return; }
        var block = btn.closest('.student-block');
        if (allBlocks().length > 1) {
            block.remove();
            updateRemoveButtons();
        }
    });

    addBtn.addEventListener('click', addStudentBlock);

    // Initialize already-rendered blocks (server-side, from form_data on error re-render)
    var initialBlocks = allBlocks();
    initialBlocks.forEach(function(block) {
        var idx = parseInt(block.getAttribute('data-idx'), 10);
        initStudentBlock(idx);
        if (idx >= nextIdx) { nextIdx = idx + 1; }
    });
    updateRemoveButtons();
})();

t.script:
document.getElementById('enquiry_form').addEventListener('submit', function(e) {
    var email = document.getElementById('field_email').value.trim();
    var phone = document.getElementById('field_phone').value.trim();
    if (!email && !phone) {
        e.preventDefault();
        alert('Please provide either an email address or a phone number.');
    }
});
